    non_gap_vals = [v for v in main_vals if v != 0]
    min_val = min(non_gap_vals)
    max_val = max(non_gap_vals)

    # Gap columns: columns with 0 in main row
    gap_cols = [c for c in range(w) if main_vals[c] == 0]

    output = [[0] * w for _ in range(h)]

    # Fill all rows above main row at gap columns
    for r in range(main_row):
        for col in gap_cols:
            if col < w // 2:
                output[r][col] = min_val
            else:
                output[r][col] = max_val

    # Fill main row: gaps with pattern values
    for col in range(w):
        main_val = main_vals[col]
        if main_val != 0:
            output[main_row][col] = main_val
        elif col < w // 2:
            output[main_row][col] = min_val
        else:
            output[main_row][col] = max_val

    # Fill rows below main row: gap columns get pattern + 1
    for r in range(main_row + 1, h):
        for col in gap_cols:
            if col < w // 2:
                output[r][col] = min_val + 1
            else:
                output[r][col] = max_val + 1

    return output



